package com.yeyamo_mobile.api.content_service.infrastructure.client;
import com.yeyamo_mobile.api.content_service.application.ContentException;import com.yeyamo_mobile.api.content_service.application.port.ReferenceVisibilityPort;import com.yeyamo_mobile.api.content_service.domain.model.PostReferenceType;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.client.*;
@Component public class ReferenceVisibilityClient implements ReferenceVisibilityPort{private final RestClient rest;private final String catalog;private final String culture;private final String place;private final String event;private final String partner;public ReferenceVisibilityClient(RestClient.Builder b,@Value("${yeyamo.services.catalog:http://catalog-service:8088}")String c,@Value("${yeyamo.services.culture:http://culture-service:8115}")String u,@Value("${yeyamo.services.place:http://place-service:8084}")String p,@Value("${yeyamo.services.event:http://event-service:8085}")String e,@Value("${yeyamo.services.partner:http://partner-service:8087}")String a){rest=b.build();catalog=c;culture=u;place=p;event=e;partner=a;}
 public void requirePublic(PostReferenceType type,String id){if(type==null||type==PostReferenceType.NONE)return;String url=switch(type){case PLACE->place+"/api/v1/places/"+id;case EVENT->event+"/api/v1/events/"+id;case ARTWORK->catalog+"/api/v1/artworks/"+id;case CULTURE_CONTENT->culture+"/api/v1/culture/contents/"+id;case LANGUAGE_LESSON->culture+"/api/v1/culture/language-lessons/"+id;case CULTURE_CHALLENGE->culture+"/api/v1/culture/challenges/"+id;case ARTISAN->partner+"/api/v1/artisans/"+id;case NONE->null;};try{rest.get().uri(url).retrieve().toBodilessEntity();}catch(RestClientResponseException ex){throw new ContentException("REFERENCE_NOT_PUBLIC","Referenced resource does not exist or is not public");}catch(ResourceAccessException ex){throw new ContentException("REFERENCE_UNAVAILABLE","Referenced resource validation is temporarily unavailable");}}
}
